contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that exercises transfer and asserts the invariant
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0));
        // Precondition: ensure this contract is the owner so it can mint/freeze/burn as needed.
        // The deployer of c is owner; the checker deploys c and then deploys this test with c passed in,
        // so msg.sender of constructor was the checker, not this contract; we cannot become owner.
        // Instead, we rely only on observable public functions available to this contract as msg.sender.

        // Bring tokens to 'from' and 'to' so balances are well-defined: try minting via owner-only call
        // but since this contract is not owner, mintToken will revert; we treat calls robustly and observe revert.
        bool mintedFromReverted;
        bool mintedToReverted;
        try c.mintToken(from, amount) {
            mintedFromReverted = false;
        } catch {
            mintedFromReverted = true;
        }
        try c.mintToken(to, 0) {
            mintedToReverted = false;
        } catch {
            mintedToReverted = true;
        }

        // Read balances before
        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);

        // Attempt transfer from 'from' to 'to' by calling transfer as this contract (msg.sender == InvMutTest)
        // But transfer uses msg.sender as source; to simulate transfer from 'from' we only can call transfer
        // as this contract, so this will move tokens from InvMutTest's own balance. Therefore, to make a meaningful
        // general property we instead check that when this contract (msg.sender) calls transfer, balances update
        // correctly for msg.sender and recipient. So reinterpret parameters: 'from' is ignored and used only for setup.

        // Ensure InvMutTest (this) has at least 'amount' tokens by trying to mint to it; observe revert flag.
        bool mintedSelfReverted;
        try c.mintToken(address(this), amount) {
            mintedSelfReverted = false;
        } catch {
            mintedSelfReverted = true;
        }

        uint256 selfBalBefore = c.balanceOf(address(this));
        uint256 recipientBalBefore = c.balanceOf(to);

        bool transferReverted;
        try c.transfer(to, amount) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        uint256 selfBalAfter = c.balanceOf(address(this));
        uint256 recipientBalAfter = c.balanceOf(to);

        // The general rule: if the transfer call did not revert, then
        // - sender's balance decreased by amount (or to zero if exact) and recipient's balance increased by amount;
        // - transfer cannot succeed if recipient is zero address (but we required to != zero above), or if either account is frozen,
        //   or if sender had insufficient balance. We express the invariant concretely as:
        // If transfer did not revert then selfBalAfter + amount == selfBalBefore AND recipientBalAfter == recipientBalBefore + amount.

        assert(transferReverted || (selfBalAfter + amount == selfBalBefore && recipientBalAfter == recipientBalBefore + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run attempts to burn `amt` tokens from this contract's balance and checks the observable effects.
    function run(uint256 amt) public payable {
        // No precondition on amt; handle revert via try/catch and observe public getters.
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool burnedReverted;
        try c.burn(amt) {
            burnedReverted = false;
        } catch {
            burnedReverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        // If burn succeeded (did not revert), then totalSupply and this contract's balance decreased by exactly amt.
        // Otherwise (reverted) no requirement is imposed.
        assert(burnedReverted || (totalBefore == totalAfter + amt && balBefore == balAfter + amt));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address to, uint256 amount) public payable {
        require(to != address(0)); // _transfer disallows zero address; keep inputs meaningful

        // Ensure this contract has tokens to send: mint tokens to this contract via owner role
        // The deployed c has owner = deployer (the checker deploys c then passes it here),
        // but InvMutTest is NOT owner. So instead we rely on initial distribution: c.balanceOf(address(this)) may be 0.
        // To make the property general without assuming ownership, we only assert a conservation condition
        // in the case the transfer call from this contract succeeds (i.e., doesn't revert).

        // Read balances before
        uint256 beforeFrom = c.balanceOf(address(this));
        uint256 beforeTo = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterFrom = c.balanceOf(address(this));
        uint256 afterTo = c.balanceOf(to);

        // If the transfer did not revert, then tokens moved from sender to recipient preserving their sum
        assert(reverted || (afterFrom + afterTo == beforeFrom + beforeTo));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, bool freeze) public payable {
        // must be the owner to call freezeAccount; this contract is the deployer/owner per spec
        // record before value
        bool before = c.frozenAccount(target);
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool after = c.frozenAccount(target);
        // If the call did not revert, then the frozenAccount getter must equal the requested value.
        assert(reverted || after == freeze);
    }
    receive() external payable { }
}

