contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters controlling the call
    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0));

        // read before-values via public getters
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalTarget = c.balanceOf(target);

        // try to call mintToken and record whether it reverted
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalTarget = c.balanceOf(target);

        // General invariant: if mint succeeded then both totalSupply and target balance increased by mintedAmount;
        // if it reverted then both observable values are unchanged.
        assert((!reverted && afterTotal == beforeTotal + mintedAmount && afterBalTarget == beforeBalTarget + mintedAmount)
               || (reverted && afterTotal == beforeTotal && afterBalTarget == beforeBalTarget));
    }

    receive() external payable { }
}
